    return res


def make_artifact(factor):
    """base64:zlib:csv signal panel (warm-up window rows)."""
    csv = factor.round(8).to_csv().encode("utf-8")
    comp = zlib.compress(csv, level=6)
    return base64.b64encode(comp).decode("ascii")


